import { FastifyPluginAsync, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { getDB } from '../utils/db';

/**
 * First-party, privacy-conscious activity tracking.
 *
 * The browser sends a small heartbeat while a tab is visible. Nothing here
 * blocks product requests: if the write fails the response is still 204 and
 * the candidate keeps working. No raw IP address is stored; `visitor_id` is a
 * random identifier generated by the browser.
 */

const heartbeatSchema = z.object({
  session_id: z.string().trim().min(8).max(120).regex(/^[A-Za-z0-9._:-]+$/),
  visitor_id: z.string().trim().min(8).max(120).regex(/^[A-Za-z0-9._:-]+$/),
  event: z.enum(['page_view', 'heartbeat', 'leave']).default('heartbeat'),
  path: z.string().trim().max(300).default('/'),
  title: z.string().trim().max(200).optional(),
  referrer: z.string().trim().max(500).optional(),
  active_seconds: z.coerce.number().int().min(0).max(120).default(0),
});

/** Group dynamic pages so "Top pages" stays readable: /jobs/<uuid> -> /jobs/:id. */
function normalizePath(value: string): string {
  const path = (value || '/').split('?')[0].split('#')[0] || '/';
  return path
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, ':id')
    .replace(/\/\d+(?=\/|$)/g, '/:id')
    .slice(0, 300);
}

function parseUserAgent(value: string) {
  const ua = value || '';
  const device = /ipad|tablet/i.test(ua)
    ? 'tablet'
    : /mobi|iphone|ipod|android/i.test(ua)
      ? 'mobile'
      : 'desktop';
  const browser = /edg\//i.test(ua)
    ? 'Edge'
    : /opr\//i.test(ua)
      ? 'Opera'
      : /chrome|crios/i.test(ua)
        ? 'Chrome'
        : /firefox|fxios/i.test(ua)
          ? 'Firefox'
          : /safari/i.test(ua)
            ? 'Safari'
            : 'Other';
  const os = /windows/i.test(ua)
    ? 'Windows'
    : /android/i.test(ua)
      ? 'Android'
      : /iphone|ipad|ipod/i.test(ua)
        ? 'iOS'
        : /mac os|macintosh/i.test(ua)
          ? 'macOS'
          : /linux/i.test(ua)
            ? 'Linux'
            : 'Other';
  return { device, browser, os };
}

async function optionalUser(request: FastifyRequest): Promise<{ id: string; role: string } | null> {
  const header = request.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) return null;
  try {
    const decoded = request.server.jwt.verify<{ id?: string; v?: number }>(header.slice(7));
    if (!decoded?.id) return null;
    const rows = await getDB().unsafe(
      `SELECT id, role, status, auth_version FROM users WHERE id = $1 LIMIT 1`,
      [decoded.id],
    );
    const row = rows[0] as any;
    if (!row || row.status === 'suspended') return null;
    if (Number(decoded.v ?? 0) !== Number(row.auth_version ?? 0)) return null;
    return { id: String(row.id), role: String(row.role || 'user') };
  } catch {
    return null;
  }
}

export const activityRoutes: FastifyPluginAsync = async (fastify) => {
  fastify.post('/heartbeat', async (request, reply) => {
    const parsed = heartbeatSchema.safeParse(request.body);
    if (!parsed.success) {
      // Never make analytics a source of product errors.
      return reply.status(204).send();
    }
    const body = parsed.data;
    const user = await optionalUser(request);
    const { device, browser, os } = parseUserAgent(String(request.headers['user-agent'] || ''));
    const countryHeader = String(request.headers['cf-ipcountry'] || request.headers['x-vercel-ip-country'] || '')
      .trim()
      .toUpperCase();
    const country = /^[A-Z]{2}$/.test(countryHeader) ? countryHeader : null;
    const isPageView = body.event === 'page_view';
    const isLeave = body.event === 'leave';
    const actorKey = user ? `u:${user.id}` : `v:${body.visitor_id}`;
    const path = normalizePath(body.path);

    try {
      const sql = getDB();
      const run = async (tx: { unsafe: (query: string, params?: any[]) => Promise<any[]> }) => {
        await tx.unsafe(
          `INSERT INTO activity_sessions
             (session_id, user_id, visitor_id, entry_path, last_path, referrer,
              device, browser, os, country, page_views, active_seconds, ended_at)
           VALUES ($1, $2, $3, $4, $4, $5, $6, $7, $8, $9, $10, $11,
                   CASE WHEN $12 THEN now() ELSE NULL END)
           ON CONFLICT (session_id) DO UPDATE SET
             user_id = COALESCE(EXCLUDED.user_id, activity_sessions.user_id),
             last_seen_at = now(),
             last_path = EXCLUDED.last_path,
             page_views = activity_sessions.page_views + EXCLUDED.page_views,
             active_seconds = activity_sessions.active_seconds + EXCLUDED.active_seconds,
             ended_at = CASE WHEN $12 THEN now() ELSE activity_sessions.ended_at END`,
          [
            body.session_id,
            user?.id ?? null,
            body.visitor_id,
            path,
            body.referrer || null,
            device,
            browser,
            os,
            country,
            isPageView ? 1 : 0,
            body.active_seconds,
            isLeave,
          ],
        );

        if (body.active_seconds > 0 || isPageView) {
          await tx.unsafe(
            `INSERT INTO activity_daily (day, actor_key, user_id, active_seconds, page_views)
             VALUES (current_date, $1, $2, $3, $4)
             ON CONFLICT (day, actor_key) DO UPDATE SET
               active_seconds = activity_daily.active_seconds + EXCLUDED.active_seconds,
               page_views = activity_daily.page_views + EXCLUDED.page_views,
               user_id = COALESCE(EXCLUDED.user_id, activity_daily.user_id)`,
            [actorKey, user?.id ?? null, body.active_seconds, isPageView ? 1 : 0],
          );
        }

        if (isPageView) {
          // The elapsed seconds sent with a page view were spent on the
          // previous page, so only the view counter belongs to this path.
          await tx.unsafe(
            `INSERT INTO activity_page_daily (day, path, views, active_seconds)
             VALUES (current_date, $1, 1, 0)
             ON CONFLICT (day, path) DO UPDATE SET
               views = activity_page_daily.views + 1`,
            [path],
          );
          await tx.unsafe(
            `INSERT INTO activity_events
               (session_id, user_id, visitor_id, kind, path, title, active_seconds)
             VALUES ($1, $2, $3, 'page_view', $4, $5, $6)`,
            [body.session_id, user?.id ?? null, body.visitor_id, path, body.title || null, 0],
          );
        } else if (body.active_seconds > 0) {
          // Heartbeats and leaves carry time actually spent on the current
          // page, so they keep the per-page breakdown accurate.
          await tx.unsafe(
            `INSERT INTO activity_page_daily (day, path, views, active_seconds)
             VALUES (current_date, $1, 0, $2)
             ON CONFLICT (day, path) DO UPDATE SET
               active_seconds = activity_page_daily.active_seconds + EXCLUDED.active_seconds`,
            [path, body.active_seconds],
          );
        }

        if (user) {
          await tx.unsafe(`UPDATE users SET last_seen_at = now() WHERE id = $1`, [user.id]);
        }
      };

      if (typeof (sql as any).begin === 'function') {
        await (sql as any).begin(run);
      } else {
        await run(sql as any);
      }
    } catch (err) {
      request.log.warn({ err }, 'activity heartbeat failed');
    }

    return reply.status(204).send();
  });
};

export default activityRoutes;
